#[inline]
fn destack_device_serial_descriptor_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut SerialPortDescriptor,
    handle: resource::SerialPortHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.trace().run_binding_without_context(
        DEVICE_SERIAL_DESCRIPTOR,
        binding.replay_payload_for(DEVICE_SERIAL_DESCRIPTOR)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_device_serial_descriptor(binding, out, handle)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_device_serial_descriptor(binding, out, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: SerialPortDescriptor = unsafe { out.read() };
                let result_recorded_id = unsafe { result_value.id.as_str()? }.to_string();
                let result_recorded_transport = result_value.transport;
                let result_recorded_name = unsafe { result_value.name.as_str()? }.to_string();
                let result_recorded_manufacturer = if let Some(value) = result_value.manufacturer {
                    let result_recorded_manufacturer_inner = unsafe { value.as_str()? }.to_string();
                    Some(result_recorded_manufacturer_inner)
                } else {
                    None
                };
                let result_recorded_product = if let Some(value) = result_value.product {
                    let result_recorded_product_inner = unsafe { value.as_str()? }.to_string();
                    Some(result_recorded_product_inner)
                } else {
                    None
                };
                let result_recorded_serial_number = if let Some(value) = result_value.serial_number
                {
                    let result_recorded_serial_number_inner =
                        unsafe { value.as_str()? }.to_string();
                    Some(result_recorded_serial_number_inner)
                } else {
                    None
                };
                let result_recorded_path = match result_value.path {
                    fs::OsPath::OsPathBytes(value) => {
                        let result_recorded_path_os_path_bytes_kind =
                            unsafe { value.kind.as_str()? }.to_string();
                        let mut result_recorded_path_os_path_bytes_bytes_inner = Vec::new();
                        for result_recorded_path_os_path_bytes_bytes_inner_item in
                            unsafe { value.bytes.0.as_slice()? }.iter().cloned()
                        {
                            let result_recorded_path_os_path_bytes_bytes_inner_item_recorded =
                                result_recorded_path_os_path_bytes_bytes_inner_item;
                            result_recorded_path_os_path_bytes_bytes_inner
                                .push(result_recorded_path_os_path_bytes_bytes_inner_item_recorded);
                        }
                        let result_recorded_path_os_path_bytes_bytes =
                            result_recorded_path_os_path_bytes_bytes_inner;
                        let result_recorded_path_os_path_bytes = fs::OspathbytesReplayRecord {
                            kind: result_recorded_path_os_path_bytes_kind,
                            bytes: result_recorded_path_os_path_bytes_bytes,
                        };
                        fs::OspathReplayRecord::OsPathBytes(result_recorded_path_os_path_bytes)
                    }
                    fs::OsPath::OsPathUtf16(value) => {
                        let result_recorded_path_os_path_utf16_kind =
                            unsafe { value.kind.as_str()? }.to_string();
                        let mut result_recorded_path_os_path_utf16_utf16_inner = Vec::new();
                        for result_recorded_path_os_path_utf16_utf16_inner_item in
                            unsafe { value.utf16.0.as_slice()? }.iter().cloned()
                        {
                            let result_recorded_path_os_path_utf16_utf16_inner_item_recorded =
                                result_recorded_path_os_path_utf16_utf16_inner_item;
                            result_recorded_path_os_path_utf16_utf16_inner
                                .push(result_recorded_path_os_path_utf16_utf16_inner_item_recorded);
                        }
                        let result_recorded_path_os_path_utf16_utf16 =
                            result_recorded_path_os_path_utf16_utf16_inner;
                        let result_recorded_path_os_path_utf16 = fs::Ospathutf16ReplayRecord {
                            kind: result_recorded_path_os_path_utf16_kind,
                            utf16: result_recorded_path_os_path_utf16_utf16,
                        };
                        fs::OspathReplayRecord::OsPathUtf16(result_recorded_path_os_path_utf16)
                    }
                };
                let result_recorded_usb_vendor_id = if let Some(value) = result_value.usb_vendor_id
                {
                    let result_recorded_usb_vendor_id_inner = value;
                    Some(result_recorded_usb_vendor_id_inner)
                } else {
                    None
                };
                let result_recorded_usb_product_id =
                    if let Some(value) = result_value.usb_product_id {
                        let result_recorded_usb_product_id_inner = value;
                        Some(result_recorded_usb_product_id_inner)
                    } else {
                        None
                    };
                let result_recorded_bluetooth_service_class_id =
                    if let Some(value) = result_value.bluetooth_service_class_id {
                        let result_recorded_bluetooth_service_class_id_inner =
                            unsafe { value.as_str()? }.to_string();
                        Some(result_recorded_bluetooth_service_class_id_inner)
                    } else {
                        None
                    };
                let result_recorded = SerialportdescriptorReplayRecord {
                    id: result_recorded_id,
                    transport: result_recorded_transport,
                    name: result_recorded_name,
                    manufacturer: result_recorded_manufacturer,
                    product: result_recorded_product,
                    serial_number: result_recorded_serial_number,
                    path: result_recorded_path,
                    usb_vendor_id: result_recorded_usb_vendor_id,
                    usb_product_id: result_recorded_usb_product_id,
                    bluetooth_service_class_id: result_recorded_bluetooth_service_class_id,
                };
                let payload = DeviceSerialDescriptorReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceSerialDescriptorReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_id = binding.store_string(value.id.as_str());
                    let value_native_transport = value.transport;
                    let value_native_name = binding.store_string(value.name.as_str());
                    let value_native_manufacturer = if let Some(value) = value.manufacturer {
                        let value_native_manufacturer_inner = binding.store_string(value.as_str());
                        Some(value_native_manufacturer_inner)
                    } else {
                        None
                    };
                    let value_native_product = if let Some(value) = value.product {
                        let value_native_product_inner = binding.store_string(value.as_str());
                        Some(value_native_product_inner)
                    } else {
                        None
                    };
                    let value_native_serial_number = if let Some(value) = value.serial_number {
                        let value_native_serial_number_inner = binding.store_string(value.as_str());
                        Some(value_native_serial_number_inner)
                    } else {
                        None
                    };
                    let value_native_path = match value.path {
                        fs::OspathReplayRecord::OsPathBytes(value) => {
                            let value_native_path_os_path_bytes_kind =
                                binding.store_string(value.kind.as_str());
                            let mut value_native_path_os_path_bytes_bytes_inner_values = Vec::new();
                            for value_native_path_os_path_bytes_bytes_inner_item in
                                value.bytes.iter().cloned()
                            {
                                let value_native_path_os_path_bytes_bytes_inner_decoded =
                                    value_native_path_os_path_bytes_bytes_inner_item;
                                value_native_path_os_path_bytes_bytes_inner_values
                                    .push(value_native_path_os_path_bytes_bytes_inner_decoded);
                            }
                            let value_native_path_os_path_bytes_bytes_inner = binding
                                .store_array(value_native_path_os_path_bytes_bytes_inner_values);
                            let value_native_path_os_path_bytes_bytes =
                                platform_fs::PathBytesAbi::<platform_abi::NativeAbi>(
                                    value_native_path_os_path_bytes_bytes_inner,
                                );
                            let value_native_path_os_path_bytes = fs::OsPathBytes {
                                kind: value_native_path_os_path_bytes_kind,
                                bytes: value_native_path_os_path_bytes_bytes,
                            };
                            fs::OsPath::OsPathBytes(value_native_path_os_path_bytes)
                        }
                        fs::OspathReplayRecord::OsPathUtf16(value) => {
                            let value_native_path_os_path_utf16_kind =
                                binding.store_string(value.kind.as_str());
                            let mut value_native_path_os_path_utf16_utf16_inner_values = Vec::new();
                            for value_native_path_os_path_utf16_utf16_inner_item in
                                value.utf16.iter().cloned()
                            {
                                let value_native_path_os_path_utf16_utf16_inner_decoded =
                                    value_native_path_os_path_utf16_utf16_inner_item;
                                value_native_path_os_path_utf16_utf16_inner_values
                                    .push(value_native_path_os_path_utf16_utf16_inner_decoded);
                            }
                            let value_native_path_os_path_utf16_utf16_inner = binding
                                .store_array(value_native_path_os_path_utf16_utf16_inner_values);
                            let value_native_path_os_path_utf16_utf16 =
                                platform_fs::PathUtf16Abi::<platform_abi::NativeAbi>(
                                    value_native_path_os_path_utf16_utf16_inner,
                                );
                            let value_native_path_os_path_utf16 = fs::OsPathUtf16 {
                                kind: value_native_path_os_path_utf16_kind,
                                utf16: value_native_path_os_path_utf16_utf16,
                            };
                            fs::OsPath::OsPathUtf16(value_native_path_os_path_utf16)
                        }
                    };
                    let value_native_usb_vendor_id = if let Some(value) = value.usb_vendor_id {
                        let value_native_usb_vendor_id_inner = value;
                        Some(value_native_usb_vendor_id_inner)
                    } else {
                        None
                    };
                    let value_native_usb_product_id = if let Some(value) = value.usb_product_id {
                        let value_native_usb_product_id_inner = value;
                        Some(value_native_usb_product_id_inner)
                    } else {
                        None
                    };
                    let value_native_bluetooth_service_class_id =
                        if let Some(value) = value.bluetooth_service_class_id {
                            let value_native_bluetooth_service_class_id_inner =
                                binding.store_string(value.as_str());
                            Some(value_native_bluetooth_service_class_id_inner)
                        } else {
                            None
                        };
                    let value_native = SerialPortDescriptor {
                        id: value_native_id,
                        transport: value_native_transport,
                        name: value_native_name,
                        manufacturer: value_native_manufacturer,
                        product: value_native_product,
                        serial_number: value_native_serial_number,
                        path: value_native_path,
                        usb_vendor_id: value_native_usb_vendor_id,
                        usb_product_id: value_native_usb_product_id,
                        bluetooth_service_class_id: value_native_bluetooth_service_class_id,
                    };
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

