#[inline]
fn destack_device_bluetooth_session_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::BluetoothDeviceHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_BLUETOOTH_SESSION_CLOSE,
        binding.replay_payload_for(DEVICE_BLUETOOTH_SESSION_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_bluetooth_close(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_bluetooth_close(binding, context, handle)
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = DeviceBluetoothSessionCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceBluetoothSessionCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_bluetooth_session_close_result(context, result)?;
    Ok(result)
}

